const SYSTEM_ID = "vagabond-app";
const RANGE = 30;
const COLOR = "#ffa733";

if (canvas.tokens.controlled.length === 0) {
  ui.notifications.warn("Select at least one token first!");
} else {
  for (const token of canvas.tokens.controlled) {
    const isLit = token.document.light.dim > 0 || token.document.light.bright > 0;

    if (!isLit) {
      await token.document.update({
        light: {
          dim: RANGE,
          bright: 0,
          angle: 360,
          color: COLOR,
          alpha: 0.4,
          priority: 0,
          negative: false,
          coloration: 1,
          luminosity: 0.5,
          attenuation: 1,
          animation: { type: "starlight", speed: 1, intensity: 1, reverse: false }
        },
        [`flags.${SYSTEM_ID}.lightType`]: "sunlight"
      });
      ui.notifications.info(`Activated sunlight for ${token.name}`);
    } else {
      await token.document.update({
        light: { dim: 0, bright: 0 },
        [`flags.${SYSTEM_ID}.lightType`]: "none"
      });
      ui.notifications.info(`${token.name} is no longer shedding sunlight`);
    }
  }
}
